_INTERCEPT = 1.41675331


def predict_stage(vector):
    vector = np.asarray(vector, dtype=np.float32)
    if vector.shape != (512,) or not np.isfinite(vector).all():
        raise ValueError('Invalid photo features')
    norm = float(np.linalg.norm(vector))
    if norm <= 0:
        raise ValueError('Empty photo features')
    logit = float(_COEF @ (vector / norm) + _INTERCEPT)
    # Clipping prevents overflow for malformed or extreme feature inputs.
    positive = float(1 / (1 + np.exp(-np.clip(logit, -80, 80))))
    index = int(positive >= .5)
    score = positive if index else 1 - positive
    return dict(stage=CLASSES[index] if score >= THRESHOLD else None,
                score=score, head_version=HEAD_VERSION, verified=False)
